function q(id,text,options,help=''){return {id,text,options,help,multi:false}}
function qm(id,text,options,help='Select all that apply.'){return {id,text,options,help,multi:true}}
function o(label,score){return {label,score}}
function points(answer){if(!answer)return 0;if(Array.isArray(answer))return answer.reduce((s,x)=>s+(x.score||0),0);return answer.score||0}
function has(answer,label){return Array.isArray(answer)?answer.some(x=>x.label===label):answer?.label===label}
function hasAny(answer,labels){return labels.some(l=>has(answer,l))}
function f(name,text,level){return {name,text,level}}
function scoreAnswers(a,max,base=0){const raw=Object.values(a).reduce((s,v)=>s+points(v),0);return Math.max(0,Math.min(100,Math.round(base+(raw/max)*(100-base))))}
function result(score,title,findings,service){return {score,title,findings,service,status:score<38?'LOW':score<68?'MODERATE':'ELEVATED',professional:score>=52}}

